// Inicializar config sin ensuciar el scope global
const APP_CONFIG = (function () {
  const entorno = 'produccion';
  const baseUrl = entorno === 'produccion'
    ? 'https://api.miapp.com'
    : 'http://localhost:3000';

  return { entorno, baseUrl };
})();

console.log(APP_CONFIG.baseUrl); // 'https://api.miapp.com'
console.log(typeof entorno);     // 'undefined' — privado

// Contador aislado — dos instancias independientes
function crearContadorAislado(inicio) {
  return (function (n) {
    let count = n;
    return {
      siguiente: () => ++count,
      valor: () => count,
    };
  })(inicio);
}

const c1 = crearContadorAislado(0);
const c2 = crearContadorAislado(100);

c1.siguiente(); // 1
c1.siguiente(); // 2
c2.siguiente(); // 101
console.log(c1.valor()); // 2
console.log(c2.valor()); // 101

